// Normalizes leads from three different intake shapes into one common
// record used by every downstream node (AI agent, GHL sync, messaging).
const j = $json;
const cfg = $('Set Workflow Defaults').first().json;

// Detect source by shape: webhook form body / Twilio SMS payload / Meta Lead Ads payload
let source, name, phone, email, message, treatmentInterest, contactId;

if (j.body?.form_type || j.body?.name) {
  // Website/form webhook
  source = 'website_form';
  name = j.body?.name || '';
  phone = j.body?.phone || '';
  email = j.body?.email || '';
  message = j.body?.message || j.body?.notes || '';
  treatmentInterest = j.body?.treatment_interest || j.body?.service || '';
  contactId = j.body?.contact_id || '';
} else if (j.From || j.Body !== undefined) {
  // Twilio SMS reply (standard Twilio webhook fields)
  source = 'sms_reply';
  name = j.ProfileName || '';
  phone = j.From || '';
  email = '';
  message = j.Body || '';
  treatmentInterest = '';
  contactId = '';
} else {
  // Meta Lead Ads
  source = 'meta_lead_ad';
  const fieldData = j.field_data || j.leadgen_id ? j : (j.body || j);
  name = fieldData.full_name || fieldData.name || '';
  phone = fieldData.phone_number || fieldData.phone || '';
  email = fieldData.email || '';
  message = '';
  treatmentInterest = fieldData.treatment_interest || fieldData.ad_name || '';
  contactId = '';
}

return [{
  json: {
    source,
    lead_name: name,
    lead_phone: phone,
    lead_email: email,
    lead_message: message,
    treatment_interest: treatmentInterest,
    contact_id: contactId,
    practice_name: cfg.PRACTICE_NAME,
    received_at: new Date().toISOString()
  }
}];

