// Deterministic lead scoring — call with { message: string, treatmentInterest: string, hasPhone: boolean, hasEmail: boolean }
const message = ($input.message || '').toLowerCase();
const interest = ($input.treatmentInterest || '').toLowerCase();

let score = 30; // baseline for any lead with contact info

const urgencyWords = ['asap', 'urgent', 'pain', 'emergency', 'today', 'this week', 'soon as possible'];
if (urgencyWords.some(w => message.includes(w))) score += 25;

const budgetWords = ['financing', 'insurance', 'payment plan', 'afford', 'cost', 'price'];
if (budgetWords.some(w => message.includes(w))) score += 10;

const highValueTreatments = ['implant', 'all-on', 'all on 4', 'all on x'];
if (highValueTreatments.some(w => interest.includes(w))) score += 20;

if (message.length > 40) score += 10; // clear, detailed message
if ($input.hasPhone) score += 5;
if ($input.hasEmail) score += 5;

score = Math.max(0, Math.min(100, score));

return { score, reasoning: `Base 30 + signals from urgency/budget/treatment-value/message-detail/contact-completeness` };

