parameters.jsCode:
const rows = $input.all().map(i => i.json);

const totalLeads = rows.length;
const highPriority = rows.filter(r => (r.lead_score || 0) >= 70).length;

const byCategory = {};
for (const r of rows) {
  const cat = r.treatment_category || 'Unknown';
  byCategory[cat] = (byCategory[cat] || 0) + 1;
}

const avgScore = totalLeads > 0
  ? Math.round(rows.reduce((sum, r) => sum + (r.lead_score || 0), 0) / totalLeads)
  : 0;

return [{
  json: {
    reportPeriod: 'Last 7 days',
    generatedAt: new Date().toISOString(),
    totalLeads,
    highPriorityLeads: highPriority,
    averageLeadScore: avgScore,
    leadsByCategory: byCategory
  }
}];

